private static String[] legacySplitKey(String resource) {
        String[] keyParts = new String[]{ "minecraft", resource };
        int i = resource.indexOf(":");
        if (i >= 0) {
            keyParts[1] = resource.substring(i + 1);
        }
        return keyParts;
    }

